 "content": "def transform(grid):
    """Propagate aligned colored markers through a grid of 8-separated panels."""
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_spans = []
    start = 0
    for sep in rows:
        if sep > start:
            row_spans.append((start, sep))
        start = sep + 1
    if start < h:
        row_spans.append((start, h))
    col_spans = []
    start = 0
    for sep in cols:
        if sep > start:
            col_spans.append((start, sep))
        start = sep + 1
    if start < w:
        col_spans.append((start, w))

    out = [row[:] for row in grid]
    markers = {}
    for r, (r0, r1) in enumerate(row_spans):
        for c, (c0, c1) in enumerate(col_spans):
            for rr in range(r0, r1):
                for cc in range(c0, c1):
                    color = grid[rr][cc]
                    if color not in (0, 8):
                        markers.setdefault(color, set()).add((r, c))

    # Each pair (or larger aligned set) marks a complete horizontal/vertical run.
    painted = {}
    for color, points in markers.items():
        for r in {p[0] for p in points}:
            cs = [c for rr, c in points if rr == r]
            if len(set(cs)) >= 2:
                for c in range(min(cs), max(cs) + 1):
                    painted.setdefault((r, c), set()).add(color)
        for c in {p[1] for p in points}:
            rs = [r for r, cc in points if cc == c]
            if len(set(rs)) >= 2:
                for r in range(min(rs), max(rs) + 1):
                    painted.setdefault((r, c), set()).add(color)

    for (pr, pc), colors in painted.items():
        if len(colors) == 1:
            color = next(iter(colors))
        elif colors == {2, 3}:
            color = 6
        else:
            color = max(colors)
        r0, r1 = row_spans[pr]
        c0, c1 = col_spans[pc]
        for rr in range(r0, r1):
            for cc in range(c0, c1):
                out[rr][cc] = color
    return out
